def _need(value,code):
    if not value:raise ValueError(code)

def _texts(sources):
    _need(type(sources)is dict and set(sources)==set(PARENTS),'ensure_scope_source_set_invalid')
    result={}
    for name,text in sources.items():
        _need(type(text)is str,'ensure_scope_source_invalid')
        text=text.replace('\r\n','\n');_need('\r'not in text,'ensure_scope_source_invalid');result[name]=text
    return result

def _digests(sources):return {name:hashlib.sha256(text.encode('utf8')).hexdigest()for name,text in sources.items()}

def restore_sources(sources):
    sources=_texts(sources);_need(_digests(sources)==OUTPUTS,'ensure_scope_output_changed');result={}
    for name,text in sources.items():
        for before,after in reversed(BLOCKS[name]):
            _need(text.count(after)==1,'ensure_scope_output_anchor_invalid');text=text.replace(after,before,1)
        result[name]=text
    _need(_digests(result)==PARENTS,'ensure_scope_parent_changed');return result

def patch_sources(sources):
    sources=_texts(sources)
    if _digests(sources)==OUTPUTS:restore_sources(sources);return sources
    _need(_digests(sources)==PARENTS,'ensure_scope_baseline_mismatch');result={}
    for name,text in sources.items():
        for before,after in BLOCKS[name]:
            _need(text.count(before)==1,'ensure_scope_parent_anchor_invalid');text=text.replace(before,after,1)
        compile(text,name,'exec');result[name]=text
    _need(_digests(result)==OUTPUTS and restore_sources(result)==sources,'ensure_scope_unrelated_change');return result
